"""Build the private owner dashboard and public analytics preferences in EN/AR."""
from html import escape
import json
from pathlib import Path
from localize_site import finish

ROOT = Path(__file__).resolve().parents[1]
CONFIG = json.loads((ROOT / 'data/analytics-config.json').read_text())
VERSION = '20260913-1'


def page(path, title, description, content, lang, private=False):
    name = 'أديب نور' if lang == 'ar' else 'Adeeb Noor'
    script = '/analytics/dashboard.js' if private else '/privacy.js'
    footer = '<footer class="analytics-footer"><div class="analytics-wrap"><span>© 2026 ' + name + '</span></div></footer>'
    html = '<!doctype html><html lang="' + lang + '"' + (' dir="rtl"' if lang == 'ar' else '') + '><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer">'
    if private:
        html += '<meta name="robots" content="noindex,nofollow,noarchive">'
    html += '<title>' + escape(title) + ' — ' + name + '</title><meta name="description" content="' + escape(description, quote=True) + '"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/analytics/dashboard.css?v=' + VERSION + '"><script defer src="' + script + '?v=' + VERSION + '"></script></head><body>' + content + footer + '</body></html>'
    target = ROOT / (('ar/' if lang == 'ar' else '') + path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(finish(html, path, lang == 'ar'))


def dashboard(lang):
    ar = lang == 'ar'
    def s(en, arabic):
        return arabic if ar else en
    title = s('Website analytics', 'إحصاءات الموقع')
    body = '<main id="main-content" class="analytics-wrap" data-analytics-dashboard data-endpoint="' + escape(CONFIG['statsEndpoint'], quote=True) + '"><header class="analytics-heading"><p class="analytics-kicker">' + s('Private owner dashboard', 'لوحة خاصة بمالك الموقع') + '</p><h1>' + title + '</h1><p>' + s('Understand visits, link activity and requests to download or print. Individual activity uses anonymous browser and session identifiers.', 'تعرّف على الزيارات ونقرات الروابط وطلبات التنزيل والطباعة. يظهر النشاط بمعرّفات مجهولة للمتصفح والجلسة.') + '</p></header>'
    body += '<section id="analytics-login" class="analytics-panel analytics-login"><h2>' + s('Open your dashboard', 'افتح لوحة الإحصاءات') + '</h2><p>' + s('Enter the private access key supplied for this dashboard. The key is never added to the page address.', 'أدخل مفتاح الدخول الخاص الذي تسلّمته لهذه اللوحة. لا يُضاف المفتاح إلى عنوان الصفحة.') + '</p><form id="analytics-login-form"><label for="analytics-key">' + s('Private access key', 'مفتاح الدخول الخاص') + '</label><input id="analytics-key" type="password" dir="ltr" disabled required minlength="43" maxlength="256" autocomplete="off" autocapitalize="none" spellcheck="false"><label class="analytics-checkbox"><input id="analytics-remember" type="checkbox"> <span>' + s('Keep access in this tab for up to eight hours', 'احتفظ بالدخول في هذه التبويبة لمدة أقصاها ثماني ساعات') + '</span></label><button type="submit" disabled>' + s('Open dashboard', 'عرض الإحصاءات') + '</button></form></section>'
    body += '<p id="analytics-status" class="analytics-status" role="status" aria-live="polite"></p><section id="analytics-content" hidden><div class="analytics-controls"><label for="analytics-range">' + s('Period', 'الفترة') + '</label><select id="analytics-range"><option value="1">' + s('Today', 'اليوم') + '</option><option value="7">' + s('Last 7 days', 'آخر ٧ أيام') + '</option><option value="30" selected>' + s('Last 30 days', 'آخر ٣٠ يومًا') + '</option><option value="90">' + s('Last 90 days', 'آخر ٩٠ يومًا') + '</option></select><button type="button" id="analytics-refresh">' + s('Refresh', 'تحديث') + '</button><button type="button" class="analytics-secondary" id="analytics-logout">' + s('Lock dashboard', 'قفل اللوحة') + '</button></div><p id="analytics-period" class="analytics-muted"></p><div id="analytics-empty" class="analytics-notice" hidden>' + s('No activity has been recorded in this period. Analytics start when tracking is activated; earlier visits cannot be recovered.', 'لم يُسجّل نشاط في هذه الفترة. تبدأ الإحصاءات من تفعيل التسجيل، ولا يمكن استعادة الزيارات السابقة.') + '</div><div class="analytics-metrics">'
    metrics = [
        ('visitors', 'Approximate visitors', 'الزوار التقريبيون', 'Distinct anonymous browsers', 'متصفحات مجهولة متميزة'),
        ('sessions', 'Sessions', 'الجلسات', 'A new session after 30 minutes of inactivity', 'جلسة جديدة بعد ٣٠ دقيقة دون نشاط'),
        ('page_views', 'Page views', 'مشاهدات الصفحات', 'Tracked page loads', 'مرات فتح الصفحات المسجّلة'),
        ('link_clicks', 'Link clicks', 'نقرات الروابط', 'All tracked link categories combined', 'مجموع فئات نقرات الروابط المسجّلة'),
        ('download_clicks', 'Download requests', 'طلبات التنزيل', 'Clicks on a downloadable file, not completion', 'نقرات على ملف للتنزيل، وليست تأكيد اكتماله'),
        ('print_requests', 'CV print / PDF requests', 'طلبات طباعة السيرة أو حفظها', 'Opening print options, not confirmation of saving', 'فتح خيارات الطباعة، وليس تأكيد حفظ الملف'),
    ]
    for key, en, arabic, sub_en, sub_ar in metrics:
        body += '<article class="analytics-metric"><h2>' + s(en, arabic) + '</h2><p class="analytics-number" data-metric="' + key + '">—</p><p>' + s(sub_en, sub_ar) + '</p></article>'
    body += '</div><section class="analytics-panel"><div class="analytics-section-heading"><h2>' + s('Daily visits', 'الزيارات اليومية') + '</h2><span class="analytics-muted">' + s('Riyadh time · approximate visitors', 'بتوقيت الرياض · زوار تقريبيون') + '</span></div><div id="analytics-daily" class="analytics-chart" role="list" aria-label="' + s('Daily approximate visitor counts', 'أعداد الزوار التقريبية يوميًا') + '"></div><p id="analytics-daily-empty" class="analytics-muted" hidden>' + s('No daily data yet.', 'لا توجد بيانات يومية بعد.') + '</p></section><div class="analytics-columns">'
    for slug, heading, headers in [
        ('pages', s('Most viewed pages', 'الصفحات الأكثر مشاهدة'), [s('Page', 'الصفحة'), s('Views', 'المشاهدات'), s('Visitors', 'الزوار')]),
        ('destinations', s('Link destinations', 'وجهات الروابط'), [s('Destination', 'الوجهة'), s('Activity', 'النشاط'), s('Clicks', 'النقرات')]),
    ]:
        body += '<section class="analytics-panel"><h2>' + heading + '</h2><div class="analytics-table-wrap" tabindex="0" role="region" aria-label="' + heading + '"><table><thead><tr>' + ''.join('<th scope="col">' + h + '</th>' for h in headers) + '</tr></thead><tbody id="analytics-' + slug + '"></tbody></table></div></section>'
    body += '</div><section class="analytics-panel"><h2>' + s('Recent activity', 'النشاط الأخير') + '</h2><p class="analytics-muted">' + s('Up to 100 recent events in the selected period. Browser identifiers do not reveal names, and one person may use several browsers.', 'حتى ١٠٠ حدث أخير ضمن الفترة المحددة. معرّفات المتصفحات لا تكشف الأسماء، وقد يستخدم الشخص أكثر من متصفح.') + '</p><div class="analytics-table-wrap analytics-events" tabindex="0" role="region" aria-label="' + s('Recent activity table', 'جدول النشاط الأخير') + '"><table><thead><tr>'
    for heading in [s('Time · Riyadh', 'الوقت · الرياض'), s('Activity', 'النشاط'), s('Page / destination', 'الصفحة / الوجهة'), s('Anonymous browser / session', 'المتصفح المجهول / الجلسة'), s('Device / source', 'الجهاز / المصدر')]:
        body += '<th scope="col">' + heading + '</th>'
    body += '</tr></thead><tbody id="analytics-events"></tbody></table></div></section><aside class="analytics-notice"><h2>' + s('How to read these numbers', 'كيف تقرأ هذه الأرقام؟') + '</h2><p>' + s('Visitors are approximate browser counts, not identified people. A browser identifier expires after 30 days. Link clicks include project, external, contact, language and download clicks; these categories are already included in the total.', 'الزوار عدد تقريبي للمتصفحات، وليس أشخاصًا معروفين بالاسم. ينتهي معرّف المتصفح بعد ٣٠ يومًا. تشمل نقرات الروابط المشاريع والروابط الخارجية والتواصل وتغيير اللغة والتنزيل؛ وهذه الفئات محسوبة بالفعل ضمن الإجمالي.') + '</p><p>' + s('A download click or CV print request does not confirm that a file was saved. Opening another project website records the outgoing click; actions inside that website require its own analytics. Visitors who opt out, use privacy signals or block tracking are not included.', 'نقرة التنزيل أو طلب طباعة السيرة لا يؤكدان حفظ ملف. يُسجّل فتح موقع مشروع آخر كنقرة انتقال؛ أما النشاط داخل ذلك الموقع فيحتاج إحصاءاته الخاصة. لا تشمل الأرقام من أوقفوا الإحصاءات أو فعّلوا إشارات الخصوصية أو أدوات حجب التتبع.') + '</p><p id="analytics-retention" class="analytics-muted"></p></aside></section><noscript><p class="analytics-notice">' + s('JavaScript is required to unlock this private dashboard.', 'يلزم تفعيل JavaScript لفتح لوحة الإحصاءات الخاصة.') + '</p></noscript></main>'
    page('analytics/index.html', title, s('Private website activity dashboard for the site owner.', 'لوحة نشاط الموقع الخاصة بمالكه.'), body, lang, private=True)


def privacy(lang):
    ar = lang == 'ar'
    def s(en, arabic):
        return arabic if ar else en
    title = s('Privacy & analytics preferences', 'الخصوصية وخيارات الإحصاءات')
    body = '<main id="main-content" class="analytics-wrap analytics-privacy" data-analytics-privacy><header class="analytics-heading"><p class="analytics-kicker">' + s('Your visit, your choice', 'زيارتك، وخيارك') + '</p><h1>' + title + '</h1><p>' + s('I use limited website analytics to understand which pages and projects help visitors and to improve the site.', 'أستخدم إحصاءات محدودة لفهم الصفحات والمشاريع التي تهم الزوار وتحسين الموقع.') + '</p></header><section class="analytics-panel"><h2>' + s('What is recorded', 'ما الذي يُسجّل؟') + '</h2><p>' + s('Page views, link clicks, download requests, CV print requests and use of the RIDI demo. Each event may include the page, a destination without its query parameters, page language, broad device category, referring hostname, time and randomly generated browser and session identifiers.', 'مشاهدات الصفحات، ونقرات الروابط، وطلبات التنزيل وطباعة السيرة، واستخدام عرض RIDI التجريبي. قد يتضمن الحدث الصفحة ووجهة الرابط دون معاملات الاستعلام، ولغة الصفحة، وفئة الجهاز العامة، واسم نطاق الموقع المُحيل، والوقت، ومعرّفين عشوائيين للمتصفح والجلسة.') + '</p><p>' + s('These analytics do not store names, email addresses, form contents, full referring addresses or raw IP addresses. Email-link clicks are recorded simply as “email”, without the address. No advertising identifiers or fingerprinting are used.', 'لا تخزّن هذه الإحصاءات أسماء أو عناوين بريد أو محتوى النماذج أو عنوان الإحالة الكامل أو عناوين IP الخام. تُسجّل نقرة رابط البريد بوصفها «بريدًا» دون العنوان. لا تُستخدم معرّفات إعلانية أو بصمة رقمية للجهاز.') + '</p></section><section class="analytics-panel"><h2>' + s('Storage and access', 'الحفظ والوصول') + '</h2><p>' + s('A random browser identifier is stored locally for up to 30 days. A session identifier is stored for the browser tab and renewed after 30 minutes of inactivity. The dashboard shows the last 90 days. Older events are removed on recording or dashboard access, with a cleanup check at most once a day. If browser storage is unavailable, temporary anonymous identifiers may be used for the current page. Clearing browser storage can create a new identifier, so visitor counts are approximate.', 'يُحفظ معرّف متصفح عشوائي محليًا لمدة أقصاها ٣٠ يومًا. يُحفظ معرّف جلسة للتبويبة ويُجدّد بعد ٣٠ دقيقة دون نشاط. تعرض اللوحة آخر ٩٠ يومًا. تُحذف الأحداث الأقدم عند التسجيل أو فتح اللوحة، مع فحص التنظيف مرة واحدة يوميًا بحد أقصى. عند تعذّر تخزين المتصفح، قد تُستخدم معرّفات مجهولة مؤقتة للصفحة الحالية. وقد يؤدي مسح بيانات المتصفح إلى إنشاء معرّف جديد؛ لذلك تبقى أعداد الزوار تقريبية.') + '</p><p>' + s('Supabase processes and stores the analytics events. Reading the dashboard requires a private owner key. As with other online services, hosting and infrastructure providers receive connection information to deliver requests; the analytics event records do not retain raw IP addresses.', 'تتولى Supabase معالجة أحداث الإحصاءات وحفظها. تتطلب قراءة اللوحة مفتاح دخول خاصًا بمالك الموقع. وكما في الخدمات عبر الإنترنت، يستقبل مزوّدو الاستضافة والبنية التحتية معلومات الاتصال لتنفيذ الطلبات؛ ولا تحتفظ سجلات أحداث الإحصاءات بعناوين IP الخام.') + '</p></section><section class="analytics-panel"><h2>' + s('Your analytics preference', 'اختيارك بشأن الإحصاءات') + '</h2><p>' + s('This website respects Do Not Track and Global Privacy Control signals. You can also stop analytics for this browser below. Your choice stays in local browser storage and does not remove previously recorded anonymous events.', 'يحترم الموقع إشارتَي عدم التتبع (Do Not Track) والتحكم العام في الخصوصية (Global Privacy Control). ويمكنك أيضًا إيقاف الإحصاءات لهذا المتصفح أدناه. يُحفظ اختيارك محليًا، ولا يحذف الأحداث المجهولة التي سُجّلت سابقًا.') + '</p><p id="privacy-status" class="analytics-status" role="status" aria-live="polite"></p><div class="analytics-controls"><button type="button" id="privacy-disable">' + s('Stop analytics in this browser', 'إيقاف الإحصاءات في هذا المتصفح') + '</button><button type="button" id="privacy-enable" class="analytics-secondary">' + s('Allow analytics in this browser', 'السماح بالإحصاءات في هذا المتصفح') + '</button></div><noscript><p>' + s('JavaScript is disabled, so this site’s analytics do not run. JavaScript is needed to change the stored preference.', 'JavaScript معطّل، لذلك لا تعمل إحصاءات الموقع. يلزم تفعيله لتغيير الخيار المحفوظ.') + '</p></noscript></section><section class="analytics-panel"><h2>' + s('What the numbers cannot tell me', 'ما الذي لا تكشفه الأرقام؟') + '</h2><p>' + s('Anonymous activity does not tell me who you are. A click on a download or print control does not prove a file was saved. Activity after leaving this website is not collected by this tracker.', 'لا يكشف النشاط المجهول هويتك. ولا تثبت نقرة التنزيل أو الطباعة أن ملفًا قد حُفظ. لا يتابع مسجّل الإحصاءات هذا النشاط بعد مغادرة الموقع.') + '</p></section></main>'
    page('privacy.html', title, s('How this website uses limited analytics and how to opt out.', 'كيفية استخدام إحصاءات الموقع المحدودة وطريقة إيقافها.'), body, lang)


if __name__ == '__main__':
    for language in ('en', 'ar'):
        dashboard(language)
        privacy(language)
    print('Built private analytics dashboard and privacy preferences in English and Arabic.')
